/**
 * Add strings a manifest translates itself, such as a workflow's steps. The map is read at each
 * lookup, so a component drawn after this reads them; English needs no entry.
 */
export function addTranslations(entries: Record<string, Record<string, string>>): void {
  Object.assign(fr, entries.fr ?? {});
}

/**
 * The catalogue's family titles read "<shape> in <container>"; both words are
 * translated here so a generated title never falls through to English.
 */
const COPY_TITLE_SHAPES: Record<string, string> = {
  Circles: "Cercles", Triangles: "Triangles", Squares: "Carrés", Pentagons: "Pentagones",
  Hexagons: "Hexagones", Octagons: "Octogones", Tans: "Tans", Dominoes: "Dominos", "L's": "L",
};
const COPY_TITLE_CONTAINERS: Record<string, string> = {
  Circles: "un cercle", Triangles: "un triangle", Squares: "un carré", Pentagons: "un pentagone",
  Hexagons: "un hexagone", Octagons: "un octogone", Tans: "un triangle rectangle", Dominoes: "un domino", "L's": "un L",
  Ellipses: "une ellipse",
};
const COPY_TITLE = /^(Circles|Triangles|Squares|Pentagons|Hexagons|Octagons|Tans|Dominoes|L's) in (Circles|Triangles|Squares|Pentagons|Hexagons|Octagons|Tans|Dominoes|L's|Ellipses)$/;
const COPY_NAME = /^(\d+) ([A-Za-z']+) in the smallest ([A-Za-z]+)$/;
/** A generated total-perimeter name also names the fixed container. */
const PERIMETER_NAME = /^(\d+) ([A-Za-z']+)(?: in an? ([a-z]+))? with the largest total (radius|side)$/;
/** A generated covering name: "3 circles covering the largest square". */
const COVERING_NAME = /^(\d+) ([A-Za-z']+) covering the largest ([a-z]+)$/;

type I18n = {
  language: Language;
  setLanguage: (language: Language) => void;
  t: (english: string) => string;
  number: (value: number, digits?: number) => string;
};

const Context = createContext<I18n | null>(null);

export function I18nProvider({ children }: { children: ReactNode }) {
  const [language, setLanguage] = useState<Language>(() =>
    window.localStorage.getItem("paper-obs-language") === "en" ? "en" : "fr",
  );
  useEffect(() => {
    document.documentElement.lang = language;
    window.localStorage.setItem("paper-obs-language", language);
  }, [language]);
  const value = useMemo<I18n>(() => ({
    language,
    setLanguage,
    t: (english) => {
      if (language === "en") return english;
      // A generated problem name ("7 hexagons in the smallest square") is built
      // from a shape and a container the dictionary already names, and a
      // catalogue title ("Hexagons in Squares") is the same two words in Title Case.
      const unitName = COPY_NAME.exec(english);
      if (unitName !== null) {
        const noun = fr[unitName[2] ?? ""] ?? unitName[2] ?? "";
        const container = fr[unitName[3] ?? ""] ?? unitName[3] ?? "";
        return `${unitName[1]} ${noun} dans le plus petit ${container}`;
      }
      const perimeterName = PERIMETER_NAME.exec(english);
      if (perimeterName !== null) {
        const noun = fr[perimeterName[2] ?? ""] ?? perimeterName[2] ?? "";
        const total = perimeterName[4] === "radius" ? "rayons" : "côtés";
        const container = perimeterName[3];
        const where = container ? ` dans ${container === "ellipse" ? "une" : "un"} ${fr[`container ${container}`] ?? container}` : "";
        return `${perimeterName[1]} ${noun}${where} avec la plus grande somme de ${total}`;
      }
      const coveringName = COVERING_NAME.exec(english);
      if (coveringName !== null) {
        const noun = fr[coveringName[2] ?? ""] ?? coveringName[2] ?? "";
        const container = fr[`container ${coveringName[3] ?? ""}`] ?? coveringName[3] ?? "";
        return `${coveringName[1]} ${noun} recouvrant le plus grand ${container}`;
      }
      const copyTitle = COPY_TITLE.exec(english);
      if (copyTitle !== null) {
        const shape = COPY_TITLE_SHAPES[copyTitle[1] ?? ""];
        const container = COPY_TITLE_CONTAINERS[copyTitle[2] ?? ""];
        if (shape !== undefined && container !== undefined) return `${shape} dans ${container}`;
      }
      return fr[english] ?? english;
    },
    number: (amount, digits = 4) => new Intl.NumberFormat(language, { maximumFractionDigits: digits }).format(amount),
  }), [language]);
  return <Context.Provider value={value}>{children}</Context.Provider>;
}

export function useI18n(): I18n {
  const value = useContext(Context);
  if (value === null) throw new Error("I18nProvider is missing");
  return value;
}
